65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Maximum number of owners a single city may contain; creating an owner in a city that
75	     *  already has this many owners is rejected with 409 Conflict. */
76	    private static final int MAX_OWNERS_PER_CITY = 50;
77	
78	    /** Maximum number of owners that may be created on a single day (by registration date); creating
79	     *  an owner once this many owners already carry today's registration date is rejected with
80	     *  429 Too Many Requests. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** When more than this many owners already carry today's registration date at creation time, the
84	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
85	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
86	
87	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
88	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    private final ClinicService clinicService;
96	
97	    private final OwnerMapper ownerMapper;
98	
99	    private final PetMapper petMapper;
100	
101	    private final VisitMapper visitMapper;
102	
103	    private final TelephoneNormalizer telephoneNormalizer;
104	
105	    private final HouseholdNormalizer householdNormalizer;
106	
107	    private final AddressNormalizer addressNormalizer;
108	
109	    private final EmailNormalizer emailNormalizer;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 TelephoneNormalizer telephoneNormalizer,
116	                                 HouseholdNormalizer householdNormalizer,
117	                                 AddressNormalizer addressNormalizer,
118	                                 EmailNormalizer emailNormalizer) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	        this.telephoneNormalizer = telephoneNormalizer;
124	        this.householdNormalizer = householdNormalizer;
125	        this.addressNormalizer = addressNormalizer;
126	        this.emailNormalizer = emailNormalizer;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
132	        Collection<Owner> owners;
133	        if (lastName != null) {
134	            owners = this.clinicService.findOwnerByLastName(lastName);
135	        } else {
136	            owners = this.clinicService.findAllOwners();
137	        }
138	        if (owners.isEmpty()) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        normalizeOwnerFields(owner);
160	        // Enforce the pre-persistence policies that can reject the new owner outright.
161	        rejectDisallowedOwnerCreation(owner);
162	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
163	        // function of last name and postcode), reject a household duplicate unless the request
164	        // declares it shares the household, and record the household size. This runs before the
165	        // identity-key check so that check sees the owner's household id.
166	        boolean declaredHouseholdMember =
167	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
168	        // Reject the create when the owner's whole derived identity key (normalized telephone,
169	        // email and household id) already matches an existing owner. This single rule subsumes the
170	        // former separate telephone, email and household duplicate checks.
171	        rejectWhenIdentityInUse(owner);
172	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
173	        // shares an existing owner's last name and postcode with a different telephone. A declared
174	        // household member is never flagged: it is a known member, not a suspected duplicate.
175	        assignPossibleDuplicate(owner, declaredHouseholdMember);
176	        // Assign the remaining create-time derived fields (namesake count, customer code,
177	        // membership number and bulk-signup warning), each fixed at creation time.
178	        assignDerivedFields(owner);
179	        this.clinicService.saveOwner(owner);
180	        // Emit an audit line for the successful create, carrying the owner id, customer code and
181	        // registration date so the create can be traced from the dedicated AUDIT log.
182	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
183	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
192	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
193	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
194	     * the sequence of create-time rejections stays readable and a new rule is added as one more
195	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
196	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
197	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
198	     * the household id has been resolved, because that key includes the household id.
199	     *
200	     * @param owner the newly mapped and normalized owner being created
201	     */
202	    private void rejectDisallowedOwnerCreation(Owner owner) {
203	        rejectWhenDailyLimitReached(owner);
204	        rejectWhenCityAtCapacity(owner);
205	    }
206	
207	    /**
208	     * Applies the household-membership rules for a newly normalized owner being created. The
209	     * household id is a deterministic function of the owner's last name and postcode, so owners
210	     * with the same last name and postcode share it automatically; it is assigned to the new owner
211	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
212	     * same last name and postcode is a member of the same household: a second such owner is rejected
213	     * as a household duplicate (409) unless the request declares it shares the household via
214	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
215	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
216	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
217	     * is resolved here before {@link #rejectWhenIdentityInUse}.
218	     *
219	     * @param owner           the newly mapped and normalized owner being created
220	     * @param sharesHousehold whether the request declared that the owner shares an existing household
221	     * @return {@code true} if the owner joined an existing household as a declared member
222	     */
223	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
224	        // Assign the deterministic household id (a pure function of last name and postcode) so every
225	        // owner with the same last name and postcode shares it automatically.
226	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
227	        // Identify any existing owners in the same household (same computed household id).
228	        List<Owner> householdMembers = sameHouseholdOwners(owner);
229	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
230	        // the request declares it shares the household, in which case create it as a declared member.
231	        boolean declaredHouseholdMember = false;
232	        if (!householdMembers.isEmpty()) {
233	            if (!sharesHousehold) {
234	                throw new HouseholdDuplicateException(
235	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
236	            }
237	            declaredHouseholdMember = true;
238	        }
239	        // Record the size of this owner's household after this create, fixed at creation time.
240	        owner.setHouseholdSize(householdMembers.size() + 1);
241	        return declaredHouseholdMember;
242	    }
243	
244	    /**
245	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
246	     * has already been resolved: the namesake count, the per-city customer code, the membership
247	     * number derived from that customer code and the registration year, and the bulk-signup warning
248	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
249	     * here keeps {@link #addOwner} focused on the high-level create sequence.
250	     *
251	     * @param owner the owner being created, already normalized and with its household resolved
252	     */
253	    private void assignDerivedFields(Owner owner) {
254	        // Record how many existing owners already share this owner's first and last name
255	        // (compared case-insensitively) before this create, fixed at creation time.
256	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
257	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
258	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
259	        // time.
260	        owner.setCustomerCode(customerCode(owner));
261	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
262	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
263	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
264	        // Flag the create when more than 80 owners have already been created on this owner's
265	        // (adjusted business-day) registration date, fixed at creation time.
266	        owner.setBulkSignupWarning(
267	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
268	    }
269	
270	    /**
271	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
272	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
273	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
274	     * the former separate telephone, email and household duplicate checks: two owners collide only
275	     * when their whole keys are equal, and members of one household with different telephones have
276	     * different keys and are both allowed.
277	     *
278	     * @param owner the owner being created, already normalized and with its household resolved
279	     */
280	    private void rejectWhenIdentityInUse(Owner owner) {
281	        String identityKey = owner.getIdentityKey();
282	        boolean inUse = existingOwners()
283	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
284	        if (inUse) {
285	            throw new DuplicateIdentityException(
286	                "An owner with identity key " + identityKey + " already exists");
287	        }
288	    }
289	
290	    /**
291	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
292	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
293	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
294	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
295	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
296	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
297	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
298	     * possible duplicate. A declared household member is never flagged: it is a known member of the
299	     * household, not a suspected duplicate. Both values are fixed at creation time.
300	     *
301	     * @param owner                   the owner being created, already normalized and confirmed not a
302	     *                                hard duplicate
303	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
304	     *                                member
305	     */
306	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
307	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
308	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
309	            .map(Owner::getId)
310	            .min(Integer::compareTo)
311	            .orElse(null);
312	        owner.setPossibleDuplicate(matchId != null);
313	        owner.setPossibleDuplicateOf(matchId);
314	    }
315	
316	    /**
317	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
318	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
319	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
320	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
321	     *
322	     * @param existing an existing owner to compare against
323	     * @param owner    the owner being created
324	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
325	     */
326	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
327	        return existing.getPostcode() != null
328	            && existing.getPostcode().equals(owner.getPostcode())
329	            && existing.getLastName() != null
330	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
331	            && existing.getTelephone() != null
332	            && !existing.getTelephone().equals(owner.getTelephone());
333	    }
334	
335	    /**
336	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
337	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
338	     *
339	     * @param owner the owner being created
340	     */
341	    private void rejectWhenDailyLimitReached(Owner owner) {
342	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
343	            throw new DailyOwnerLimitExceededException(
344	                "The maximum number of owners that may be created today has already been reached");
345	        }
346	    }
347	
348	    /**
349	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
350	     * or more owners, with 409 Conflict.
351	     *
352	     * @param owner the owner being created
353	     */
354	    private void rejectWhenCityAtCapacity(Owner owner) {
355	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
356	            throw new CityCapacityExceededException(
357	                "The city " + owner.getCity() + " already contains the maximum number of owners");
358	        }
359	    }
360	
361	    /**
362	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
363	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
364	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
365	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
366	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
367	     * server's current date. Canonicalising the address here, before the household checks read it,
368	     * ensures duplicate detection and the shared household id both compare the normalized form.
369	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
370	     * duplicate, household and customer-code rules.
371	     *
372	     * @param owner the newly mapped owner to canonicalize
373	     */
374	    private void normalizeOwnerFields(Owner owner) {
375	        // Normalize the address on create so it is stored and returned in canonical form and every
376	        // later comparison (household duplicate detection and the shared household id) uses it.
377	        // A value that is blank after normalization is rejected with 400.
378	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
379	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
380	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
381	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
382	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
383	        // Store the (already syntactically validated) email lower-cased so it is persisted and
384	        // returned in canonical form. A missing email is left untouched.
385	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
386	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
387	        // canonicalization so the comparison sees the lower-cased value.
388	        rejectDisposableEmailDomain(owner.getEmail());
389	        // Validate the optional postcode against the fixed range for the city's region. A postcode
390	        // is checked only when present (it is optional); one out of range for the city's region is
391	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
392	        // value is left unchanged.
393	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
394	        // Reject a supplied registration date that is later than the server's current date with
395	        // 400, before any defaulting or business-day adjustment, so a future date is never
396	        // persisted regardless of how the roll-forward would move it.
397	        rejectFutureRegistrationDate(owner.getRegistrationDate());
398	        // Default the registration date to the server's current date when the client did not
399	        // supply one, then roll the effective date forward to a business day so a Saturday or
400	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
401	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
402	        // date-derived field (such as the membership number's year segment) and the per-day
403	        // create-limit are computed from.
404	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
405	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
406	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
407	    }
408	
409	    /**
410	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
411	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
412	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
413	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
414	     * domain part is left untouched.
415	     *
416	     * @param email the owner's canonicalized email, or {@code null} when absent
417	     */
418	    private void rejectDisposableEmailDomain(String email) {
419	        if (email == null) {
420	            return;
421	        }
422	        int at = email.lastIndexOf('@');
423	        if (at < 0) {
424	            return;
425	        }
426	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
427	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
428	            throw new DisposableEmailException(
429	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
430	        }
431	    }
432	
433	    /**
434	     * Rejects a supplied registration date that is later than the server's current date with a
435	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
436	     * accepted, and a date on or before today is left for the normal defaulting and business-day
437	     * adjustment.
438	     *
439	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
440	     */
441	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
442	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
443	            throw new InvalidRegistrationDateException(
444	                "The supplied registration date " + registrationDate + " is later than the current date");
445	        }
446	    }
447	
448	    /**
449	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
450	     * following Monday, while a weekday is returned unchanged. Applied to the effective
451	     * registration date (whether supplied in the request or defaulted to the server date) so the
452	     * persisted registration date, every value derived from it and the per-day create-limit all
453	     * use the adjusted business day.
454	     *
455	     * @param date the effective registration date
456	     * @return the same date if it is a weekday, otherwise the following Monday
457	     */
458	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
459	        java.time.LocalDate adjusted = date;
460	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
461	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
462	            adjusted = adjusted.plusDays(1);
463	        }
464	        return adjusted;
465	    }
466	
467	    /**
468	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
469	     * region derived from the owner's postcode (falling back to the city, via
470	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
471	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
472	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
473	     * owner's region and identity fields.
474	     *
475	     * @param owner the owner being created, already normalized
476	     * @return the formatted customer code
477	     */
478	    private String customerCode(Owner owner) {
479	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
480	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
481	        return region + "-" + hash8;
482	    }
483	
484	    /**
485	     * Streams the existing owners that the create-time rules match a new owner against. Every
486	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
487	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
488	     * own matching criterion rather than on how the existing owners are retrieved.
489	     *
490	     * @return a stream over all existing owners
491	     */
492	    private Stream<Owner> existingOwners() {
493	        return this.clinicService.findAllOwners().stream();
494	    }
495	
496	    /**
497	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
498	     * fix the per-city sequence of an owner's customer code at creation time.
499	     *
500	     * @param city the city of the owner being created
501	     * @return the number of existing owners in a matching city
502	     */
503	    private int countOwnersInCity(String city) {
504	        return (int) existingOwners()
505	            .filter(existing -> existing.getCity() != null
506	                && existing.getCity().equalsIgnoreCase(city))
507	            .count();
508	    }
509	
510	    /**
511	     * Counts the existing owners whose registration date is the given adjusted business day. Used
512	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
513	     * owners already carry that business day as their registration date.
514	     *
515	     * @param date the adjusted business-day registration date to match
516	     * @return the number of existing owners registered on that date
517	     */
518	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
519	        return (int) existingOwners()
520	            .filter(existing -> date.equals(existing.getRegistrationDate()))
521	            .count();
522	    }
523	
524	    /**
525	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
526	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
527	     *
528	     * @param customerCode     the owner's customer code
529	     * @param registrationDate the owner's registration date
530	     * @return the formatted membership number
531	     */
532	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
533	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
534	    }
535	
536	    /**
537	     * Returns the existing owners in the given owner's household, i.e. those sharing its
538	     * deterministic household id (the same last name and postcode). The id is computed via
539	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
540	     * whitespace are treated as the same household. Centralising how "the same household" is matched
541	     * here keeps that definition in one place for every caller.
542	     *
543	     * @param owner the owner being created, with its household id already assigned
544	     * @return the existing owners in the owner's household (possibly empty)
545	     */
546	    private List<Owner> sameHouseholdOwners(Owner owner) {
547	        String householdId = owner.getHouseholdId();
548	        return existingOwners()
549	            .filter(existing -> householdId.equals(
550	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
551	            .toList();
552	    }
553	
554	    /**
555	     * Counts the existing owners who share the given first and last name, compared
556	     * case-insensitively. Used to fix an owner's namesake count at creation time.
557	     *
558	     * @param firstName the first name of the owner being created
559	     * @param lastName  the last name of the owner being created
560	     * @return the number of existing owners with a matching first and last name
561	     */
562	    private int countNamesakes(String firstName, String lastName) {
563	        return (int) existingOwners()
564	            .filter(existing -> existing.getFirstName() != null
565	                && existing.getFirstName().equalsIgnoreCase(firstName)
566	                && existing.getLastName() != null
567	                && existing.getLastName().equalsIgnoreCase(lastName))
568	            .count();
569	    }
