571	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
572	    @Override
573	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
574	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
575	        if (currentOwner == null) {
576	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
577	        }
578	        currentOwner.setAddress(ownerFieldsDto.getAddress());
579	        currentOwner.setCity(ownerFieldsDto.getCity());
580	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
581	        currentOwner.setLastName(ownerFieldsDto.getLastName());
582	        // Normalize the telephone to canonical E.164 form so it is stored and returned
583	        // consistently with create; an unformattable value is rejected with 400.
584	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
585	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
586	        this.clinicService.saveOwner(currentOwner);
587	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
588	    }
