605	        Owner owner = this.clinicService.findOwnerById(ownerId);
606	        if (owner == null) {
607	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	        }
609	        HttpHeaders headers = new HttpHeaders();
610	        Pet pet = petMapper.toPet(petFieldsDto);
611	        owner.setId(ownerId);
612	        pet.setOwner(owner);
613	        pet.getType().setName(null);
614	        this.clinicService.savePet(pet);
615	        PetDto petDto = petMapper.toPetDto(pet);
616	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
617	            .buildAndExpand(pet.getId()).toUri());
618	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
