624	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
625	        if (currentOwner != null) {
626	            Pet currentPet = this.clinicService.findPetById(petId);
627	            if (currentPet != null) {
628	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
629	                currentPet.setName(petFieldsDto.getName());
