17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.formatForDisplay(owner.getTelephone()))")
28	    @Mapping(target = "membershipPoints",
29	        expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel",
31	        expression = "java(membershipLevel(membershipPoints(owner)))")
32	    @Mapping(target = "locality",
33	        expression = "java(owner.getCustomerCode() != null "
34	            + "? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')) "
35	            + ": org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity(), owner.getPostcode()))")
36	    @Mapping(target = "contactPreference",
37	        expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) "
38	            + "? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
39	    @Mapping(target = "checkDigit",
40	        expression = "java(owner.getCustomerCode() == null ? null "
41	            + ": org.springframework.samples.petclinic.util.LuhnCheckDigit.compute(owner.getCustomerCode()))")
42	    @Mapping(target = "ageBand",
43	        expression = "java(owner.getBirthDate() == null || owner.getRegistrationDate() == null ? null "
44	            + ": (java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears() < 18 "
45	            + "? OwnerDto.AgeBandEnum.MINOR "
46	            + ": java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears() < 65 "
47	            + "? OwnerDto.AgeBandEnum.ADULT : OwnerDto.AgeBandEnum.SENIOR))")
48	    OwnerDto toOwnerDto(Owner owner);
