60	    /**
61	     * Computes the owner's membership points: 0 to start, plus 2 when an email address is present,
62	     * plus 1 when the namesake count is 0, plus 2 for a household of 3 or more, and plus 3 for
63	     * tenure over 365 days.
64	     */
65	    default int membershipPoints(Owner owner) {
66	        int points = 0;
67	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
68	            points += 2;
69	        }
70	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
71	            points += 1;
72	        }
73	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
74	            points += 2;
75	        }
76	        if (owner.getRegistrationDate() != null
77	            && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
78	            points += 3;
79	        }
80	        return points;
81	    }
82	
83	    /**
84	     * Maps membership points to a membership level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4
85	     * for 6 or more.
86	     */
87	    default int membershipLevel(int membershipPoints) {
88	        if (membershipPoints <= 1) {
89	            return 1;
90	        }
91	        if (membershipPoints <= 3) {
92	            return 2;
93	        }
94	        if (membershipPoints <= 5) {
95	            return 3;
96	        }
97	        return 4;
98	    }
99	
100	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
101	        OwnerPageDto ownerPageDto = new OwnerPageDto();
102	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
103	        ownerPageDto.setPage(ownerPage.getNumber());
104	        ownerPageDto.setSize(ownerPage.getSize());
105	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
106	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
107	        return ownerPageDto;
108	    }
109	}
