17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	
21	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
22	
23	/**
24	 * Validates an owner's optional 4-digit postcode against the fixed range for the region of their
25	 * city. The region is resolved from the city via {@link LocalityResolver}, and each known region
26	 * has an inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A postcode is
27	 * validated only when present: an owner without a postcode is accepted. A city whose region is not
28	 * in the table ({@code "UNKNOWN"}) accepts any 4-digit postcode. A postcode that falls outside its
29	 * region's range is rejected with {@link InvalidPostcodeException} (a 400).
30	 */
31	public final class PostcodeValidator {
32	
33	    /** Region -> inclusive 4-digit postcode range {low, high}; regions absent here accept any. */
34	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
35	        "NSW", new int[] {2000, 2099},
36	        "VIC", new int[] {3000, 3099},
37	        "QLD", new int[] {4000, 4099});
38	
39	    private PostcodeValidator() {
40	    }
41	
42	    /**
43	     * Validates the supplied postcode for the given city. Does nothing when the postcode is
44	     * {@code null} (postcode is optional). When present, the value is expected to already be a
45	     * 4-digit string (guaranteed by the request-level bean validation); it is accepted when the
46	     * city's region is unknown, and otherwise must fall within the region's inclusive range.
47	     *
48	     * @param city     the owner's city (may be {@code null})
49	     * @param postcode the owner's postcode (may be {@code null})
50	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
51	     */
52	    public static void validate(String city, String postcode) {
53	        if (postcode == null) {
54	            return;
55	        }
56	        int[] range = REGION_POSTCODES.get(LocalityResolver.resolve(city));
57	        if (range == null) {
58	            return;
59	        }
60	        int value = Integer.parseInt(postcode);
61	        if (value < range[0] || value > range[1]) {
62	            throw new InvalidPostcodeException(
63	                "Postcode " + postcode + " is out of range for city " + city);
64	        }
65	    }
66	}
